// .claude/settings.json — política de segurança completa
{
  "permissions": {
    "allow": [
      "Bash(git:*)",
      "Bash(npm test:*)",
      "Bash(pnpm lint:*)",
      "Read(**)",
      "Edit(src/**)",
      "Edit(tests/**)"
    ],
    "deny": [
      "Bash(rm -rf:*)",
      "Bash(curl:*)",
      "Bash(wget:*)",
      "Bash(ssh:*)",
      "Bash(git push --force:*)",
      "Bash(sudo:*)",
      "Bash(npm publish:*)",
      "Edit(.env*)",
      "Edit(**/secrets/**)",
      "Write(/etc/**)",
      "Write(~/.ssh/**)"
    ],
    "ask": [
      "Bash(git push:*)",
      "Bash(docker:*)",
      "Edit(package.json)",
      "Edit(Dockerfile)"
    ]
  },
  "sandbox": {
    "network": {
      "deniedDomains": [
        "pastebin.com",
        "transfer.sh",
        "*.ngrok.io"
      ]
    }
  },
  "disableSkillShellExecution": false,
  "defaultMode": "plan"
}

// Hierarquia (override de cima pra baixo):
// enterprise (managed policy) > ~/.claude/settings.json > .claude/settings.json > .claude/settings.local.json

// Nota importante sobre find em 2026:
// "Bash(find:*)" NÃO auto-aprova mais "find -exec" ou "find -delete"
// Isso é tratado como ação separada e pede confirmação
